function calculateStatistics(data: number[]) {
  const seen = new Set();
  let sum = 0;
  let min = data[0];
  let max = data[0];
  let hasDuplicates = false;

  for (const value of data) {
    sum += value;
    if (value < min) min = value;
    if (value > max) max = value;
    if (seen.has(value)) hasDuplicates = true;
    seen.add(value);
